    public static class AutoChessGeneratedExecutionEvaluator
    {
        public static bool TryEvaluateExecuteDamage(
            float baseValue,
            float maxValue,
            bool isClampMax,
            float baseDamage,
            float missingHealthCoefficient,
            float minDamage,
            float maxDamage,
            out AutoChessGeneratedExecutionOutputRecord output)
        {
            output = default;
            if (baseValue <= 0f)
                return false;

            var effectiveMaxValue = isClampMax ? maxValue : baseValue;
            var missingHealth = math.max(0f, effectiveMaxValue - baseValue);
            var clampedMaxDamage = math.max(minDamage, maxDamage);
            var damage = math.clamp(
                baseDamage + missingHealth * missingHealthCoefficient,
                minDamage,
                clampedMaxDamage);
            if (damage <= 0f)
                return false;

            output = new AutoChessGeneratedExecutionOutputRecord(damage);
            return true;
        }
    }

